import javax.swing.*;import java.awt.*;import java.awt.image.*;import javax.imageio.*;import java.io.*;
public class ForgotCheck {
 static Object get(Object o,String n)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 static void layout(Container c){c.doLayout();for(var x:c.getComponents())if(x instanceof Container t)layout(t);}
 public static void main(String[]a)throws Exception{SwingUtilities.invokeAndWait(()->{com.formdev.flatlaf.FlatLightLaf.setup();var f=new QuizoraApp.Ui.Auth.forgotPasswordForm();try{var next=(JButton)get(f,"nextButton");next.doClick();if((int)get(f,"step")!=0)throw new AssertionError();((JTextField)get(f,"emailField")).setText("student@example.com");next.doClick();if((int)get(f,"step")!=1)throw new AssertionError();((JTextField)get(f,"codeField")).setText("12345");next.doClick();if((int)get(f,"step")!=1)throw new AssertionError();((JTextField)get(f,"codeField")).setText("123456");next.doClick();if((int)get(f,"step")!=2)throw new AssertionError();((JPasswordField)get(f,"passwordField")).setText("example");((JPasswordField)get(f,"confirmPasswordField")).setText("different");next.doClick();if(!((JLabel)get(f,"statusLabel")).getText().contains("matching"))throw new AssertionError();((JPasswordField)get(f,"confirmPasswordField")).setText("example");next.doClick();if(!((JLabel)get(f,"statusLabel")).getText().contains("not been changed"))throw new AssertionError();((JButton)get(f,"backButton")).doClick();((JButton)get(f,"backButton")).doClick();if((int)get(f,"step")!=0)throw new AssertionError();layout(f.getContentPane());var im=new BufferedImage(1000,500,BufferedImage.TYPE_INT_RGB);var g=im.createGraphics();f.getContentPane().printAll(g);g.dispose();ImageIO.write(im,"png",new File("Build/forgot-password-preview.png"));System.out.println("Passed: email validation, six digits, password matching, preview completion, back navigation.");}catch(Exception e){throw new RuntimeException(e);}finally{f.dispose();}});}}
